/* cppi::5ac31157be0f2476440bb0631bd55041afa8e6826c32896b984ba264d01b9483 */
select distinct request_id, start_date, end_date, pool, strategy_alternative, weight, start_date as business_date
from performance.tpm_tpm_atp_weights where request_id = 
(select max(request_id) from performance.tpm_tpm_atp_weights where start_date = '2025-04-29' and end_date = '2025-04-29')
and start_date = '2025-04-29' and end_date = '2025-04-29'
